package app.furibudget

/** Generated by tools/make_sounds.py. Lists every built-in sound so the shrinker keeps the raw files. */
object SoundCatalog {
    val styles = listOf("soft", "pop", "coins", "water", "retro")
    val events = listOf("keypad", "saved", "paid", "deleted", "goal")

    /** Resource id of the built-in sound for [style] and [event], or null for "silent" and unknown names. */
    fun res(style: String, event: String): Int? = when (style to event) {
        "soft" to "keypad" -> R.raw.snd_soft_keypad
        "soft" to "saved" -> R.raw.snd_soft_saved
        "soft" to "paid" -> R.raw.snd_soft_paid
        "soft" to "deleted" -> R.raw.snd_soft_deleted
        "soft" to "goal" -> R.raw.snd_soft_goal
        "pop" to "keypad" -> R.raw.snd_pop_keypad
        "pop" to "saved" -> R.raw.snd_pop_saved
        "pop" to "paid" -> R.raw.snd_pop_paid
        "pop" to "deleted" -> R.raw.snd_pop_deleted
        "pop" to "goal" -> R.raw.snd_pop_goal
        "coins" to "keypad" -> R.raw.snd_coins_keypad
        "coins" to "saved" -> R.raw.snd_coins_saved
        "coins" to "paid" -> R.raw.snd_coins_paid
        "coins" to "deleted" -> R.raw.snd_coins_deleted
        "coins" to "goal" -> R.raw.snd_coins_goal
        "water" to "keypad" -> R.raw.snd_water_keypad
        "water" to "saved" -> R.raw.snd_water_saved
        "water" to "paid" -> R.raw.snd_water_paid
        "water" to "deleted" -> R.raw.snd_water_deleted
        "water" to "goal" -> R.raw.snd_water_goal
        "retro" to "keypad" -> R.raw.snd_retro_keypad
        "retro" to "saved" -> R.raw.snd_retro_saved
        "retro" to "paid" -> R.raw.snd_retro_paid
        "retro" to "deleted" -> R.raw.snd_retro_deleted
        "retro" to "goal" -> R.raw.snd_retro_goal
        else -> null
    }
}
